<?php
namespace Tests\Feature;
use Tests\TestCase;
use Tests\Support\AcademicFixture;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\DB;
use App\Models\User;
use App\Services\{TermWorkflowService,EnrollmentService,EnrollmentPipelineService};
class HtmlParityTest extends TestCase {
 use RefreshDatabase,AcademicFixture;
 private array $f;
 protected function setUp():void{parent::setUp();$this->f=$this->fixture();$this->actingAs($this->f['registrar']);}
 private function open():void{DB::table('periods')->where('id',$this->f['period'])->update(['academic_year'=>'2026-2027','start_date'=>'2026-11-01','end_date'=>'2027-03-01']);app(TermWorkflowService::class)->activate($this->f['period']);}
 public function test_grade_summary_upcoming_prerequisites_and_credit_results():void{$future=$this->row('subjects',['code'=>'NEXT102','name'=>'Next semester','units'=>3]);$failed=$this->row('subjects',['code'=>'REPEAT101','name'=>'Repeat subject','units'=>3]);foreach([[$future,2],[$failed,1]] as [$subject,$semester])$this->row('curriculum_subjects',['curriculum_id'=>$this->f['curriculum'],'subject_id'=>$subject,'year_level'=>1,'semester'=>$semester]);$this->row('prerequisites',['subject_id'=>$future,'required_subject_id'=>$this->f['subject']]);$this->row('academic_records',['student_id'=>$this->f['student'],'subject_id'=>$this->f['subject'],'period_id'=>$this->f['period'],'status'=>'CREDITED']);$this->row('academic_records',['student_id'=>$this->f['student'],'subject_id'=>$failed,'period_id'=>$this->f['period'],'grade'=>'5.00','status'=>'FAILED']);$this->actingAs($this->f['user'])->get('/grades')->assertOk()->assertSee('Upcoming')->assertSee('Prerequisites')->assertSee('CREDITED')->assertViewHas('summary',['Passed / credited'=>1,'Failed / incomplete'=>1,'No grade yet'=>0,'Subjects in program'=>3]);}
 public function test_student_and_professor_account_details_are_scoped_read_only():void{$this->open();$this->actingAs($this->f['user'])->get('/account/password')->assertOk()->assertSee('ADM-1')->assertSee('BSIT 1A')->assertSee('Information Technology');$professor=User::factory()->create(['role'=>'professor','must_change_password'=>false]);DB::table('professors')->where('id',$this->f['professor'])->update(['user_id'=>$professor->id]);$this->row('professors',['employee_id'=>'PRIVATE-OTHER','name'=>'Other employee','department'=>'Other','employment_type'=>'PART_TIME']);$this->actingAs($professor)->get('/account/password')->assertOk()->assertSee('EMP-1')->assertSee('IT001')->assertSee('Authorized subjects')->assertDontSee('PRIVATE-OTHER');$this->post('/records/'.$this->f['student'],['year_level'=>2,'classification'=>'regular'])->assertForbidden();}
 public function test_pipeline_has_seven_stages_and_acceptance_is_an_immediate_milestone():void{$this->open();$this->get('/registrar')->assertOk()->assertSee('Enrollment pipeline')->assertSee('Awaiting evaluation')->assertViewHas('pipeline',fn($counts)=>count($counts)===7&&$counts['new']===1);$id=app(EnrollmentService::class)->propose($this->f['student'],$this->f['period'],[$this->f['offering']]);$this->get('/students?stage=proposed&period_id='.$this->f['period'])->assertOk()->assertSee($this->f['user']->name);$this->actingAs($this->f['user']);app(EnrollmentService::class)->decide($id,1,true,null);$counts=app(EnrollmentPipelineService::class)->counts();$this->assertSame(1,$counts['accepted']);$this->assertSame(1,$counts['finalized']);$this->assertSame(0,$counts['proposed']);$this->actingAs($this->f['registrar'])->get('/students?stage=new&period_id='.$this->f['period'])->assertOk()->assertDontSee($this->f['user']->name);}
 public function test_academic_year_summary_preserves_recorded_standing():void{$this->open();DB::table('students')->where('id',$this->f['student'])->update(['year_level'=>2]);$this->get('/academic-years?academic_year=2026-2027')->assertOk()->assertSee('BSIT 1A')->assertViewHas('students',fn($rows)=>$rows->count()===1&&(int)$rows->first()->year_level===1);$this->actingAs($this->f['user'])->get('/academic-years')->assertForbidden();}
 public function test_send_to_all_sections_only_publishes_waiting_regular_students_once():void{$this->open();DB::table('subjects')->where('id',$this->f['subject'])->update(['weekly_hours'=>1]);app(TermWorkflowService::class)->lock($this->f['period'],1);$data=['period_id'=>$this->f['period'],'section_ids'=>[$this->f['section']]];$this->post('/sections/send',$data)->assertSessionHasNoErrors()->assertSessionHas('status','1 student(s) updated.');$this->assertDatabaseHas('enrollments',['student_id'=>$this->f['student'],'version'=>1,'status'=>'proposed']);$this->post('/sections/send',$data)->assertSessionHasNoErrors();$this->assertDatabaseCount('proposal_items',1);}
 public function test_registrar_composer_retains_head_draft_and_queue_shows_units():void{DB::table('students')->where('id',$this->f['student'])->update(['classification'=>'irregular']);$this->row('special_cases',['student_id'=>$this->f['student'],'period_id'=>$this->f['period'],'request'=>'Back subject','status'=>'approved','requested_subject_ids'=>json_encode([$this->f['subject']])]);$head=User::factory()->create(['role'=>'department_head','must_change_password'=>false]);$this->row('department_head_programs',['user_id'=>$head->id,'program_id'=>$this->f['program']]);$this->actingAs($head);$id=app(EnrollmentService::class)->propose($this->f['student'],$this->f['period'],[$this->f['offering']],true,true);$this->actingAs($this->f['registrar'])->get('/special-enrollment')->assertOk()->assertSee('IT001')->assertSee('Units')->assertSee('Add subjects / build proposal');$this->get('/enrollments?draft_id='.$id)->assertOk()->assertViewHas('preselected',[$this->f['offering']])->assertViewHas('selectedStudent',$this->f['student']);$this->actingAs($this->f['user'])->get('/enrollments?draft_id='.$id)->assertForbidden();}
 public function test_head_directory_links_requested_subjects_to_scoped_evaluation():void{$this->open();DB::table('students')->where('id',$this->f['student'])->update(['classification'=>'irregular']);$case=$this->row('special_cases',['student_id'=>$this->f['student'],'period_id'=>$this->f['period'],'request'=>'Back subject','requested_subject_ids'=>json_encode([$this->f['subject']])]);$head=User::factory()->create(['role'=>'department_head','must_change_password'=>false]);$this->row('department_head_programs',['user_id'=>$head->id,'program_id'=>$this->f['program']]);$this->actingAs($head)->get('/special-students')->assertOk()->assertSee('Evaluate request')->assertSee('IT001')->assertDontSee('By academic year');}
 public function test_prerequisites_must_be_in_an_earlier_shared_curriculum_term():void{$later=$this->row('subjects',['code'=>'LATER','name'=>'Later term','units'=>3]);$this->row('curriculum_subjects',['curriculum_id'=>$this->f['curriculum'],'subject_id'=>$later,'year_level'=>1,'semester'=>2]);$this->post('/academic/prerequisites',['subject_id'=>$this->f['subject'],'required_subject_id'=>$later,'alternative_group'=>0])->assertSessionHasErrors('academic');$this->post('/academic/prerequisites',['subject_id'=>$later,'required_subject_id'=>$this->f['subject'],'alternative_group'=>0])->assertSessionHasNoErrors();}
 public function test_room_availability_toggle_preserves_issued_cor():void{$id=app(EnrollmentService::class)->propose($this->f['student'],$this->f['period'],[$this->f['offering']]);$this->actingAs($this->f['user']);app(EnrollmentService::class)->decide($id,1,true,null);$snapshot=DB::table('cor_versions')->value('snapshot');$this->actingAs($this->f['registrar'])->post('/academic/rooms/'.$this->f['room'].'/deactivate')->assertSessionHasNoErrors();$this->assertDatabaseHas('rooms',['id'=>$this->f['room'],'active'=>false]);$this->assertSame($snapshot,DB::table('cor_versions')->value('snapshot'));$this->get('/enrollments/'.$id.'/cor')->assertOk();$this->post('/academic/rooms/'.$this->f['room'].'/activate')->assertSessionHasNoErrors();}
 public function test_section_promotion_uses_year_end_guards_and_runs_once():void{$this->open();DB::table('periods')->where('id',$this->f['period'])->update(['semester'=>2]);app(TermWorkflowService::class)->close($this->f['period']);$this->row('academic_records',['student_id'=>$this->f['student'],'subject_id'=>$this->f['subject'],'period_id'=>$this->f['period'],'grade'=>'2.00','status'=>'PASSED']);$data=['period_id'=>$this->f['period'],'section_ids'=>[$this->f['section']],'confirm'=>1];$this->post('/sections/promote',$data)->assertSessionHasNoErrors()->assertSessionHas('status','1 student(s) updated.');$this->assertDatabaseHas('students',['id'=>$this->f['student'],'year_level'=>2]);$this->post('/sections/promote',$data)->assertSessionHas('workflow_errors');$this->assertDatabaseCount('student_promotions',1);}
}
